def save_new_version(file, new_chunks):
    version = metadata.commit_version(file.id, chunk_hashes(new_chunks))  # 1) record version
    for c in new_chunks:
        if not blobstore.exists(hash(c)):
            blobstore.put(hash(c), c)                                     # 2) upload chunks
    # another client may read the version between step 1 and step 2
